{
  "defaultAction": "SCMP_ACT_ALLOW",
  "syscalls": [
    {
      "names": [
        "keyctl",
        "add_key",
        "request_key",
        "ptrace",
        "process_vm_writev"
      ],
      "action": "SCMP_ACT_ERRNO",
      "errnoRet": 1
    }
  ]
}

#!/bin/sh
# Transparent SSH transport to this case's dedicated QEMU guest, not a command emulator.
exec ssh -i /opt/vm/client-key -o IdentitiesOnly=yes -o BatchMode=yes -o StrictHostKeyChecking=yes -o UserKnownHostsFile=/opt/vm/known_hosts -o ConnectTimeout=2 -p 2200 root@127.0.0.1 "$@"
